<?php
$uid = (int)$u['id'];
handle('budget_save', function () use ($uid) { $cat = strtolower(trim((string)$_POST['category'])); $lim = cents($_POST['limit'] ?? ''); if ($cat === '' || $lim <= 0) throw new AppError('Enter a category and a positive limit.'); q('INSERT INTO budgets (user_id,group_id,category,monthly_limit) VALUES (?,0,?,?) ON DUPLICATE KEY UPDATE monthly_limit=VALUES(monthly_limit)', [$uid, mb_substr($cat, 0, 30), dec($lim)]); return 'Budget saved.'; });
handle('budget_delete', function () use ($uid) { q('DELETE FROM budgets WHERE id=? AND user_id=?', [(int)$_POST['id'], $uid]); return 'Budget removed.'; });
$s = Cash::safe($uid); $fc = Cash::forecast($uid); $ins = Cash::insights($uid); $bs = Cash::budgetStatus($uid);
echo page_head('Safe to spend', 'An explainable limit built from your balance, known bills, savings goals and a safety buffer.');
$line = fn($l, $c, $cls = '') => '<dt>' . e($l) . '</dt><dd class="' . $cls . '">' . e(($c < 0 ? '-' : '') . money(dec(abs($c)))) . '</dd>';
$calc = '<dl class="kv">' . $line('Current BDT balance', $s['balance_c']) . $line('minus bills due in ' . $s['horizon'] . ' days (' . count($s['bills']) . ')', -$s['bills_c'], 'neg') . $line('minus monthly savings plan toward goals', -$s['savings_c'], 'neg') . $line('minus safety buffer', -$s['buffer_c'], 'neg') . '</dl><div class="total-row"><span>Safe to spend (conservative)</span><span class="' . ($s['safe_c'] < 0 ? 'neg' : 'pos') . '">' . mny(dec($s['safe_c'])) . '</span></div><dl class="kv" style="margin-top:8px">' . $line('plus known income expected (' . count($s['income']) . ')', $s['income_c'], 'pos') . $line('Safe to spend if that income arrives', $s['safe_with_income_c']) . $line('Spread evenly per day', $s['daily_c']) . '</dl><p class="hint">Income is not counted in the conservative figure because it may arrive late. Change the inputs in Recurring, Pockets and Settings.</p>';
$cm = ''; foreach ($ins as [$ty, $m]) $cm .= '<div class="alert ' . ($ty === 'warn' ? 'warn' : ($ty === 'ok' ? 'ok' : 'info')) . '">' . icon($ty === 'ok' ? 'check' : 'alert') . '<div>' . e($m) . '</div></div>';
echo '<div class="grid g2">' . card('How it is calculated', $calc) . card('Insights', $cm) . '</div><div style="height:16px"></div>';
$as = '<ul style="margin:8px 0 0;padding-left:18px">'; foreach ($fc['assumptions'] as $a) $as .= '<li>' . e($a) . '</li>'; $as .= '</ul>';
echo card('30-day cash-flow forecast', chart_line($fc['series']) . '<dl class="kv" style="margin-top:12px">' . $line('Balance today', $fc['start_c']) . $line('Projected in 30 days', $fc['end_c']) . $line('Lowest projected balance', $fc['min_c'], $fc['min_c'] < 0 ? 'neg' : '') . '</dl>' . ($fc['shortfall'] ? '<div class="alert err" style="margin-top:12px">' . icon('alert') . '<div><strong>Shortfall warning:</strong> your balance is projected to go below zero on ' . e(fdate($fc['shortfall']['date'], false)) . ' (' . mny(dec($fc['shortfall']['balance_c'])) . '). Move a bill date, pause a subscription, or add funds before then.</div></div>' : '<div class="alert ok" style="margin-top:12px">No shortfall projected in the next 30 days.</div>') . '<details><summary>Assumptions (this is an estimate, not a fact)</summary>' . $as . '</details>');
$rows = []; foreach ($bs as $b) { $pct = (float)$b['monthly_limit'] > 0 ? 100 * (float)$b['spent'] / (float)$b['monthly_limit'] : 0; $rows[] = [e(ucfirst($b['category'])) . ($b['group'] ? '<div class="hint">Shared: ' . e($b['group']) . '</div>' : ''), progress($pct, $pct >= 100 ? 'bad' : ($pct >= 80 ? 'warn' : '')) . '<div class="hint">' . mny($b['spent']) . ' of ' . mny($b['monthly_limit']) . ' (' . round($pct) . '%)</div>', $b['group_id'] > 0 ? '' : form_start('budget_delete', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$b['id'] . '">' . btn('Remove', 'secondary sm') . '</form>']; }
echo '<div style="height:16px"></div><div class="grid g-main">' . card('Budgets this month', tbl(['Category', 'Progress', ''], $rows, 'No budgets yet. Create one to track a category.')) . card('Set a personal budget', form_start('budget_save') . field('Category', 'category', 'text', '', 'required list="cats" maxlength="30" placeholder="food, shopping, transfer"') . '<datalist id="cats"><option>food</option><option>shopping</option><option>transfer</option><option>entertainment</option><option>bills</option></datalist>' . field('Monthly limit (BDT)', 'limit', 'text', '', 'required inputmode="decimal"') . btn('Save budget') . '</form><p class="hint">Group budgets are managed inside each group.</p>') . '</div>';
